const mark = () => page.evaluate(() => {
  let n = 0;
  for (const el of document.querySelectorAll('body *')) {
    const hasText = [...el.childNodes].some(c => c.nodeType === 3 && c.textContent.trim());
    const r = el.getBoundingClientRect();
    if (hasText && r.width > 0 && r.height > 0 && getComputedStyle(el).fontSize === '8px') {
      el.setAttribute('data-tiny-8px', '1');
      n++;
    }
  }
  return n;
});

for (const path of ['/ops/radar', '/ops/operations', '/ops/launchpad', '/ops/rules']) {
  await page.goto(path);
  await page.waitForLoadState('networkidle');
  await mark();
  // Symptom: the radar clock and the admin label render at 8px; no visible text should.
  await expect(page.locator('[data-tiny-8px]')).toHaveCount(0);
}
